4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the owner's telephone on create: strips every non-digit character and then
9	 * requires exactly 10 digits, mutating the validated request in place so later steps store
10	 * and return the normalized 10-digit value. Anything that is not exactly 10 digits after
11	 * stripping is rejected 400 via {@link InvalidTelephoneException}.
12	 */
13	public class NormalizeOwnerTelephone {
14	
15	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
16	        String digits = toDigits(request.getTelephone());
17	        if (digits.length() != 10) {
18	            throw new InvalidTelephoneException(
19	                    "Telephone must contain exactly 10 digits after removing non-digit characters");
20	        }
21	        request.setTelephone(digits);
22	    }
23	
24	    /**
25	     * The single source of truth for what "same telephone" means: strips every non-digit
26	     * character, treating {@code null} as empty. Shared with {@link CheckOwnerTelephoneUnique}
27	     * so the request side and stored owners are normalized identically.
28	     */
29	    static String toDigits(String telephone) {
30	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
31	    }
