package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Normalizes the owner's optional email: when present it must be a syntactically valid
 * address, and is stored and returned lower-cased. The validated request is mutated in
 * place so later steps persist and return the normalized value. A missing (null) email is
 * left untouched; a present but invalid one is rejected 400 via {@link InvalidEmailException}.
 */
public class NormalizeOwnerEmail {

    /**
     * A pragmatic syntactic check: a non-empty local part, an {@code @}, and a domain with
     * at least one dot, none of the three parts containing whitespace or a second {@code @}.
     */
    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String email = request.getEmail();
        if (email == null) {
            return; // email is optional
        }
        String normalized = email.toLowerCase(Locale.ROOT);
        if (!EMAIL.matcher(normalized).matches()) {
            throw new InvalidEmailException("Email must be a syntactically valid address");
        }
        request.setEmail(normalized);
    }
}

